import sys,json,subprocess,re
from pathlib import Path
sys.path.insert(0,str(Path.cwd()/'scripts'))
import note_review_queue as q
OUT=Path(__file__).resolve().parent;ROOT=Path.cwd();PREFIX=OUT.relative_to(ROOT).as_posix()
def read(p):return json.loads(Path(p).read_text())
def sha(p):return q.raw_sha(Path(p).read_bytes())
def write(n,d):(OUT/n).write_bytes(q.encoded(d))
def gitraw(head,path):return subprocess.check_output(['git','show',head+':'+path])
j=read(OUT/'assignment.json');packet=read(OUT/'visible-input.json');ctx=read(OUT/'related-context.json');head=ctx['source_head'];units=packet['units']
assert packet['job']==j and len(units)==20 and sum(len(u['claims']) for u in units)==442
assert sha(OUT/'related-context.json')=='e381a2e313dace01534ca358394861bca223f6748fb8d32a2a5ec821aa75fefe'
ledgerraw=gitraw(head,q.LEDGER);ledgers={r['unit_id']:r for r in map(json.loads,ledgerraw.splitlines())}
body_sources={}
for path in ['notes/guide.json',*q.git(ROOT,'ls-tree','-r','--name-only',head,'revisions/notes').splitlines()]:
 if path!='notes/guide.json' and not re.fullmatch(r'revisions/notes/\d{4}-\d{2}-\d{2}-[^/]+\.json',path):continue
 raw=gitraw(head,path);d=json.loads(raw);items=[u for ch in d.get('chapters',[]) for u in ch.get('units',[])]+d.get('units',[])
 for u in items:
  if u.get('id') in j['unit_bindings'] and isinstance(u.get('body'),str) and q.raw_sha(u['body'].encode())==j['unit_bindings'][u['id']]['body_sha256']:body_sources.setdefault(u['id'],[]).append({'path':path,'source_raw_sha256':q.raw_sha(raw)})
for u in units:
 uid=u['unit']['id'];b=j['unit_bindings'][uid];assert u['binding']==b and q.raw_sha(u['unit']['body'].encode())==b['body_sha256'] and body_sources[uid]
 census=read(b['census_path']);assert sha(b['census_path'])==b['census_sha256']==q.raw_sha(gitraw(head,b['census_path']))
 cu=next(x for x in census['units'] if x['unit_id']==uid);cc=[c for c in census['claims'] if c['unit_id']==uid]
 assert cu==u['census_unit'] and cc==u['claims'] and q.digest(cu)==b['census_unit_record_sha256'] and {c['claim_id']:q.digest(c) for c in cc}==b['claim_record_sha256s']
 row=ledgers[uid];fields={k:row.get(k) for k in ('unit_id','chapter_id','actual_effective_body_sha256','atomic_claim_census_complete','atomic_claim_census_status','atomic_census_source','atomic_census_notes_revision','atomic_claim_ids','atomic_source_blocked_count')};assert q.digest(fields)==b['ledger_binding_sha256']
assert len(ctx['questions'])==33 and not ctx['missing_related_ids'] and len(ctx['derived'])==13
question_source_hashes={}
for x in ctx['questions']:
 raw=gitraw(head,x['source_path']);question_source_hashes[x['source_path']]=q.raw_sha(raw);d=json.loads(raw);records=d['questions'] if isinstance(d,dict) else d;cur=next(z for z in records if z['question_id']==x['question']['question_id'])
 for k in ['stem','choices','correct_choice_ids','explanation']:assert cur[k]==x['question'][k]
derived_hash_count=0
for d in ctx['derived']:
 v=d['visible_item']
 for uid in set(v.get('note_units',[]))&set(j['unit_ids']):
  if 'source_hashes' in v:assert v['source_hashes'][uid]==j['unit_bindings'][uid]['body_sha256'];derived_hash_count+=1
for f in ['site/notes/study-data.js','site/notes/refresh-data.js']:assert q.raw_sha(gitraw(head,f))==ctx['source_files'][f]
extra=read(OUT/'extra-direct-body-questions.json');assert len(extra['questions'])==3 and extra['source_head']==head
write('input-current-verification.json',{'job_id':j['job_id'],'current_context_source_head':head,'body_count':20,'claim_count':442,'all_assignment_packet_census_unit_claim_hashes_match':True,'all_current_committed_census_raw_and_ledger_bindings_match':True,'committed_sources_containing_exact_actual_body':body_sources,'strict_inventory_observation':'Root strict current native inventory observed actual effective bodies and all claim/census SHA before assignment; worker reads explicit packet and verifies all hashes plus committed source bytes and ledger bindings. Worker did not call load_notes, synthesize inventory, mock or alter any guard.','related_questions_visible_fields_match_current_committed_source':33,'related_question_source_file_sha256s':question_source_hashes,'extra_direct_body_questions_read':3,'derived_full_visible_items_read':13,'assigned_body_source_hash_entries_checked':derived_hash_count,'glossary_boundary':'Four glossary items have no source_hashes field; read as supplied visible definitions, not falsely counted as hash-bearing items.','canonical_release_credit':0,'question_audit_credit':0})
