def authority(name,section):
 m=read(OUT/'sources'/f'{name}.meta.json');ext=m['raw_extension'];assert m['retrieval_kind']=='LIVE_DIRECT_HTTPS_GET' and m['http_status']==200
 return {'source_type':'PUBLIC_OFFICIAL','official_url':m['official_url'],'exact_section':section,'law_checked_date':'2026-11-04','version_or_effective_date_status':VERSIONS[name],'evidence_path':PREFIX+'/sources/'+name+ext,'evidence_sha256':sha(OUT/'sources'/(name+ext)),'text_evidence_path':PREFIX+'/sources/'+name+'.txt','text_evidence_sha256':sha(OUT/'sources'/f'{name}.txt'),'retrieval_metadata_path':PREFIX+'/sources/'+name+'.meta.json','retrieval_metadata_sha256':sha(OUT/'sources'/f'{name}.meta.json')}
